package in.anumati.platform.incentive; import in.anumati.platform.regulatory.*; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="incentive_conditions") public class IncentiveCondition {@Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="scheme_id",nullable=false) private IncentiveScheme scheme; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private ConditionField field; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ConditionOperator operator; @Enumerated(EnumType.STRING) @Column(name="value_type",nullable=false,length=20) private ValueType valueType; @Column(nullable=false,length=500) private String value; @Column(name="sequence_number",nullable=false) private int sequenceNumber; protected IncentiveCondition(){} public IncentiveCondition(IncentiveScheme s,ConditionField f,ConditionOperator o,ValueType v,String value,int seq){id=UUID.randomUUID();scheme=s;field=f;operator=o;valueType=v;this.value=value;sequenceNumber=seq;} public UUID getId(){return id;}public IncentiveScheme getScheme(){return scheme;}public ConditionField getField(){return field;}public ConditionOperator getOperator(){return operator;}public ValueType getValueType(){return valueType;}public String getValue(){return value;}public int getSequenceNumber(){return sequenceNumber;}}
